// SCRIPT CHECK v2 (17.11.26) - one shared rule for audits, the nightly QA report and every Lokalise write.
// Flags a TARGET translation when it contains: (1) letters from a writing system the language does not use
// (Chinese 谋 in Turkish, Cyrillic "о" in Spanish, Russian in Thai), (2) encoding garbage (Ã©, â€™, Ä±, �, NUL).
// Latin is always allowed (brands, formats). Characters that also appear in the English source are ignored.
function scriptCheck(iso, text, src) {
  const SCRIPTS = ['Han','Hiragana','Katakana','Hangul','Cyrillic','Greek','Arabic','Hebrew','Thai','Devanagari','Georgian','Armenian','Bengali','Tamil','Ethiopic','Khmer','Lao','Myanmar'];
  const ALLOW = { el: ['Greek'], uk: ['Cyrillic'], ru: ['Cyrillic'], bg: ['Cyrillic'], sr: ['Cyrillic'], mk: ['Cyrillic'], kk: ['Cyrillic'], be: ['Cyrillic'], mn: ['Cyrillic'], ja: ['Han','Hiragana','Katakana'], zh: ['Han'], ko: ['Hangul','Han'], th: ['Thai'], ar: ['Arabic'], fa: ['Arabic'], ur: ['Arabic'], he: ['Hebrew'], hi: ['Devanagari'], mr: ['Devanagari'], ne: ['Devanagari'], ka: ['Georgian'], hy: ['Armenian'], bn: ['Bengali'], ta: ['Tamil'], am: ['Ethiopic'], km: ['Khmer'], lo: ['Lao'], my: ['Myanmar'] };
  const HOMO = { 'а':'a','е':'e','о':'o','р':'p','с':'c','у':'y','х':'x','і':'i','ј':'j','ѕ':'s','А':'A','В':'B','Е':'E','К':'K','М':'M','Н':'H','О':'O','Р':'P','С':'C','Т':'T','Х':'X','п':'p','ο':'o','α':'a','ε':'e','ι':'i','κ':'k','ν':'v','ρ':'p','τ':'t','υ':'u','Ο':'O','Α':'A','Ε':'E','Κ':'K','Μ':'M','Ν':'N','Ρ':'P','Τ':'T','Χ':'X' };
  const MOJI = /[\u00c3\u00c2\u00c4\u00c5\u00d0\u00d1][\u0080-\u009f\u00a1-\u00bf]|\u00e2\u20ac|\u00ef\u00bf\u00bd|\ufffd|\u0000/g;
  const t = String(text || ''); const s = String(src || '');
  const lang = String(iso || '').toLowerCase().split(/[-_]/)[0];
  if (/^(pst|ps|xx|zz|qps)$/.test(lang) || !t) { return null; }
  const allow = ALLOW[lang] || [];
  const bad = {}; const latinLang = !allow.length;
  for (const ch of Array.from(t)) {
    if (ch.charCodeAt(0) < 0x370 || s.indexOf(ch) !== -1) { continue; }
    let sc = null; for (const x of SCRIPTS) { if (new RegExp('\\p{Script=' + x + '}', 'u').test(ch)) { sc = x; break; } }
    if (sc && allow.indexOf(sc) === -1) { (bad[sc] = bad[sc] || {})[ch] = 1; }
  }
  const moji = Array.from(new Set((t.match(MOJI) || []).filter(function (m) { return s.indexOf(m) === -1; })));
  const kinds = Object.keys(bad);
  if (!kinds.length && !moji.length) { return null; }
  const chars = []; for (const k in bad) { for (const c in bad[k]) { chars.push(c + ' (U+' + c.codePointAt(0).toString(16).toUpperCase().padStart(4, '0') + ', ' + k + ')'); } }
  for (const m of moji) { chars.push(JSON.stringify(m)); }
  // Suggested fix only when it is mechanical: look-alike Cyrillic/Greek letters inside a Latin-script word.
  let fix = '';
  if (latinLang && !moji.length && kinds.every(function (k) { return k === 'Cyrillic' || k === 'Greek'; })) {
    const f = t.replace(/[\p{Script=Cyrillic}\p{Script=Greek}]/gu, function (c) { return HOMO[c] || c; });
    if (!/[\p{Script=Cyrillic}\p{Script=Greek}]/u.test(f)) { fix = f; }
  }
  const what = kinds.length ? kinds.join('/') + ' characters in a ' + lang + ' translation' : 'garbled encoding';
  return { rule: 'encoding: wrong script or garbled text', kinds: kinds.concat(moji.length ? ['mojibake'] : []), chars: chars.slice(0, 6).join(', '), issue: 'Corrupted characters: ' + what + (moji.length && kinds.length ? ' + garbled encoding' : '') + ' (' + chars.slice(0, 4).join(', ') + ').', fix: fix };
}

// SCRIPT GUARD v2 (17.11.26): runs before every Lokalise write. Blocks the whole write if any translation about to be
// written has letters from the wrong writing system or garbled encoding. A character that the same key carries in
// 3+ other languages (e.g. a native language name) is allowed.
const bad = []; const grouped = new WeakSet();
