    const r = scriptCheck(x.iso, x.text, (x.src || '') + shared);
    if (r) { bad.push({ path: path, iso: x.iso, why: r.issue, text: x.text.slice(0, 80) }); }
  }
}
function walk(o, path) {
  if (Array.isArray(o)) {
    const trs = o.filter(function (v) { return v && typeof v === 'object' && !Array.isArray(v) && (v.language_iso || v.lang_iso || v.iso || v.langIso) && (typeof v.translation === 'string' || typeof v.text === 'string'); })
      .map(function (v) { return { iso: v.language_iso || v.lang_iso || v.iso || v.langIso, text: typeof v.translation === 'string' ? v.translation : v.text, src: v.source || v.en || '' }; });
